import * as THREE from 'three/webgpu';
import { texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load texture
  const imageTexture = ctx.textureLoader.load(config.imageUrl || '/prism-mock/home/nodes/cta-hero-isolated.png');

  // Create plane geometry (512:320 aspect ratio = 1.6)
  const geometry = new THREE.PlaneGeometry(3.2, 2.0);

  // Create material with TSL texture node
  const texNode = texture(imageTexture);
  const material = new THREE.MeshBasicMaterial({
    colorNode: texNode,
    transparent: true,
  });

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Add text content using fontAtlas
  if (config.textContent && config.textContent[0]) {
    const textStr = typeof config.textContent[0] === 'string' 
      ? config.textContent[0] 
      : config.textContent[0].text;

    if (textStr && ctx.fontAtlas) {
      const textMesh = ctx.fontAtlas(textStr, {
        font: 'Lora',
        size: 0.34,
        weight: 400,
        color: '#16161d',
        align: 'center',
      });
      textMesh.position.z = 0.15;
      group.add(textMesh);
    }
  }

  // Apply scene placement
  if (config.scenePosition) {
    if (Array.isArray(config.scenePosition)) {
      group.position.set(config.scenePosition[0], config.scenePosition[1], config.scenePosition[2]);
    } else {
      group.position.copy(config.scenePosition);
    }
  } else {
    group.position.set(0, 3, 0);
  }

  if (config.sceneRotation) {
    if (Array.isArray(config.sceneRotation)) {
      group.rotation.set(config.sceneRotation[0], config.sceneRotation[1], config.sceneRotation[2]);
    } else {
      group.rotation.copy(config.sceneRotation);
    }
  }

  if (config.sceneScale) {
    if (Array.isArray(config.sceneScale)) {
      group.scale.set(config.sceneScale[0], config.sceneScale[1], config.sceneScale[2]);
    } else {
      group.scale.copy(config.sceneScale);
    }
  }

  // Initialize handlers
  group.userData.handlers = {};

  // Cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    imageTexture.dispose();
  };

  return group;
}
